hudson.tasks.Shell.command:
#!/bin/bash
set -euo pipefail
export HOME="$WORKSPACE/.home"
mkdir -p "$HOME"
export PATH="$HOME/.local/bin:$PATH"
command -v uv >/dev/null 2>&1 || curl -LsSf https://astral.sh/uv/install.sh | sh >/dev/null
export JENKINS_URL="https://pxb.cd.percona.com"
TOOL='git+https://github.com/nogueiraanderson/jenkins-preview@main'

echo "== cloning $FORK_URL @ $BRANCH"
rm -rf checkout
git clone --quiet --branch "$BRANCH" "$FORK_URL" checkout
cd checkout
if [ ! -f .jenkins-preview.json ]; then
  echo "NOTE: this fork/branch carries no .jenkins-preview.json; using the curated pxb defaults (sets: pxb-8.0, pxb-8.1, pxb-9.x)"
  cat > .jenkins-preview.json <<'CURATED_SETS'
{
  "sets": {
    "pxb-8.0": {
      "yaml_dir": "pxb/v2/jenkins",
      "jobs": ["percona-xtrabackup-8.0-compile-pipeline", "percona-xtrabackup-8.0-test-pipeline"],
      "stages": {
        "compile": ["percona-xtrabackup-8.0-compile-pipeline"],
        "test": ["percona-xtrabackup-8.0-test-pipeline"]
      },
      "stage_order": ["compile", "test"],
      "consumes": {"test": "compile"}
    },
    "pxb-8.1": {
      "yaml_dir": "pxb/v2/jenkins",
      "jobs": ["percona-xtrabackup-8.1-compile-pipeline", "percona-xtrabackup-8.1-test-pipeline"],
      "stages": {
        "compile": ["percona-xtrabackup-8.1-compile-pipeline"],
        "test": ["percona-xtrabackup-8.1-test-pipeline"]
      },
      "stage_order": ["compile", "test"],
      "consumes": {"test": "compile"}
    },
    "pxb-9.x": {
      "yaml_dir": "pxb/v2/jenkins",
      "jobs": ["percona-xtrabackup-9.x-compile-pipeline", "percona-xtrabackup-9.x-test-pipeline"],
      "stages": {
        "compile": ["percona-xtrabackup-9.x-compile-pipeline"],
        "test": ["percona-xtrabackup-9.x-test-pipeline"]
      },
      "stage_order": ["compile", "test"],
      "consumes": {"test": "compile"}
    }
  }
}
CURATED_SETS
fi
echo "== publishing preview"
EXTRA=()
if [ "${ALLOW_FOREIGN_FETCH:-false}" = "true" ]; then EXTRA+=(--allow-foreign-fetch); fi
uvx --from "$TOOL" jenkins-preview up --repo "$FORK_URL" --ref "$BRANCH" --set "$SET" --name "$NAME" --no-root-view "${EXTRA[@]}"
